function personalizedName(){return prefs.displayName||(liveSummary.connected?liveSummary.profile?.name:'')||(prefs.language==='zh'?'Orbit 用户':'Orbit User');}
function applyProfile(){const name=personalizedName(),avatar=prefs.avatar||'';for(const el of document.querySelectorAll('.top-avatar,.profile-avatar')){el.replaceChildren();if(avatar){const image=document.createElement('img');image.src=avatar;image.alt=name;el.append(image);}else el.textContent=Array.from(name)[0]?.toUpperCase()||'U';}document.querySelector('.profile strong').textContent=name;document.querySelector('.top-avatar').setAttribute('aria-label',name+' '+(prefs.language==='en'?'profile settings':'个人设置'));}
function personalProfileModal(){const english=prefs.language==='en',tr=(en,zh)=>english?en:zh;openModal(tr('Your profile','个人设置'),`<form data-form="profile"><div class="profile-edit"><div class="profile-preview avatar">${prefs.avatar?'<img src="'+escapeHtml(prefs.avatar)+'" alt="'+tr('Your avatar','你的头像')+'">':escapeHtml(Array.from(personalizedName())[0]||'U')}</div><div><button type="button" class="secondary-btn" data-action="upload-avatar">${tr('Upload avatar','上传头像')}</button><button type="button" class="text-link" data-action="remove-avatar">${tr('Reset avatar','恢复默认头像')}</button></div></div><input type="hidden" name="avatar" id="profile-avatar-value" value="${escapeHtml(prefs.avatar||'')}"><label for="profile-display-name">${tr('Display name','显示名称')}</label><input id="profile-display-name" name="displayName" maxlength="100" value="${escapeHtml(prefs.displayName||'')}" placeholder="${escapeHtml(personalizedName())}"><p class="connection-help">${tr('Your profile is saved on this device.','个人设置保存在此设备。')}</p><div class="profile-options"><button type="button" class="account-option" data-action="profile-google">${tr('Google connection','Google 连接')} ↗</button><button type="button" class="account-option" data-action="login-settings">${tr('Passwords and sign-in','密码与登录')} ↗</button></div><div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">${tr('Close','关闭')}</button><button type="submit" class="primary-btn">${tr('Save and close','保存并关闭')}</button></div></form>`);}
async function uploadProfileAvatar(){const result=await window.orbitDesktop.pickAvatar();if(!result.ok){toast(result.error);return;}if(result.canceled)return;document.getElementById('profile-avatar-value').value=result.avatar;const preview=document.querySelector('.profile-preview');preview.replaceChildren();const image=document.createElement('img');image.src=result.avatar;image.alt=prefs.language==='en'?'Your avatar':'你的头像';preview.append(image);}
function removeProfileAvatar(){document.getElementById('profile-avatar-value').value='';document.querySelector('.profile-preview').textContent=Array.from(personalizedName())[0]||'U';}
async function savePersonalProfile(formData){const result=await window.orbitDesktop.saveProfile({displayName:formData.get('displayName'),avatar:formData.get('avatar')});if(!result.ok){toast(result.error);return;}prefs.displayName=result.displayName;prefs.avatar=result.avatar;saveUiPreferences();closeModal();render();toast(prefs.language==='en'?'Profile saved.':'个人设置已保存。');}
async function checkOrbitUpdate(){const button=document.getElementById('check-update'),status=document.getElementById('update-status');button.disabled=true;const tr=(en,zh)=>prefs.language==='en'?en:zh;status.textContent=tr('Checking for updates…','正在检查更新…');try{const result=await window.orbitDesktop.checkUpdate();if(!result.ok)throw Error(result.error);if(!result.updating)status.textContent=tr('You’re up to date.','当前已是最新版本。')+' '+result.version;}catch(error){status.textContent=error.message;}finally{button.disabled=false;}}
window.orbitDesktop?.onUpdateStatus(data=>{const element=document.getElementById('update-status');if(element)element.textContent=data.message;});
